   258      krb5_ui_4 cbuffers;
   259      krb5_error_code code;
   260      krb5_pac pac;
   261
   262      cbuffers = src->pac->cBuffers;
   263      if (cbuffers != 0)
   264          cbuffers--;
   265
   266      header_len = sizeof(PACTYPE) + cbuffers * sizeof(PAC_INFO_BUFFER);
   267
   268      pac = (krb5_pac)malloc(sizeof(*pac));
   269      if (pac == NULL)
   270          return ENOMEM;
   271
   272      pac->pac = k5memdup(src->pac, header_len, &code);
   273      if (pac->pac == NULL) {
   274          free(pac);
   275          return code;
