   277
   278      code = krb5int_copy_data_contents(context, &src->data, &pac->data);
   279      if (code != 0) {
   280          free(pac->pac);
   281          free(pac);
   282          return ENOMEM;
   283      }
   284
   285      pac->verified = src->verified;
   286      *dst = pac;
   287
   288      return 0;
